const item = items[0].json;

const msg = String(item.message_text || '').trim();

let advisorStep = String(
  item.advisor_step ||
  item.property_advisor_step ||
  'Main Menu'
).trim();

let investorProfileType = item.investor_profile_type || item.property_investor_profile_type || '';
let partnersCount = item.partners_count || item.property_partners_count || '';
let investmentSector = item.investment_sector || item.property_investment_sector || '';
let city = item.city || item.property_city || '';

let reply = '';
let nextAdvisorStep = advisorStep;

if (advisorStep === 'Investor Type') {
  if (msg === '1') investorProfileType = 'Saudi/Resident';
  if (msg === '2') investorProfileType = 'Foreign Investor';

  nextAdvisorStep = 'Partners Count';
  reply = `ممتاز.

اختر عدد الملاك:

1️⃣ مالك واحد
2️⃣ شريكان
3️⃣ ثلاثة شركاء أو أكثر

يرجى الرد برقم الخيار فقط.`;
}

else if (advisorStep === 'Partners Count') {
  if (msg === '1') partnersCount = '1';
  if (msg === '2') partnersCount = '2';
  if (msg === '3') partnersCount = '3+';

  nextAdvisorStep = 'Investment Sector';
  reply = `اختر نوع النشاط:

1️⃣ تجاري
2️⃣ تقني
3️⃣ صناعي
4️⃣ خدمي
5️⃣ أخرى

يرجى الرد برقم الخيار فقط.`;
}

else if (advisorStep === 'Investment Sector') {
  const sectors = {
    '1': 'Commercial',
    '2': 'Technology',
    '3': 'Industrial',
    '4': 'Services',
    '5': 'Other',
  };

  investmentSector = sectors[msg] || 'Other';

  nextAdvisorStep = 'City';
  reply = `اختر المدينة:

1️⃣ الرياض
2️⃣ جدة
3️⃣ الدمام
4️⃣ مكة
5️⃣ مدينة أخرى

يرجى الرد برقم الخيار فقط.`;
}

else if (advisorStep === 'City') {
  const cities = {
    '1': 'Riyadh',
    '2': 'Jeddah',
    '3': 'Dammam',
    '4': 'Makkah',
    '5': 'Other',
  };

  city = cities[msg] || 'Other';

  nextAdvisorStep = 'Package Type';
  reply = `اختر نوع الخدمة:

1️⃣ باقة تأسيس كاملة
2️⃣ استشارة فقط

يرجى الرد برقم الخيار فقط.`;
}

else if (advisorStep === 'Package Type') {
  const packageType = msg === '1' ? 'Full Setup Package' : 'Consultation Only';

  nextAdvisorStep = 'Completed';
  reply = `تم استلام البيانات الأساسية.

سيتم مراجعة التفاصيل وتجهيز المسار المناسب لك من الفريق المختص.`;
}

else {
  nextAdvisorStep = 'Investor Type';
  reply = `مرحباً، لتحديد مسار تأسيس الشركة المناسب، اختر نوع المستثمر:

1️⃣ سعودي / مقيم
2️⃣ مستثمر أجنبي

يرجى الرد برقم الخيار فقط.`;
}

return [
  {
    json: {
      ...item,
      text_body: reply,
      reply_text: reply,
      output: reply,
      advisor_step: nextAdvisorStep,
      investor_profile_type: investorProfileType,
      partners_count: partnersCount,
      investment_sector: investmentSector,
      city,
      send_ready: true,
      route_to_menu: false,
      route_to_ai: false,
      route_to_advisor: true,
    },
  },
];
